<script setup lang="ts">
import {computed,onMounted,reactive,ref} from "vue";
import ProductHistoryButton from "./ProductHistoryButton.vue";
import {useI18n} from "vue-i18n";
import {ElMessageBox,type FormInstance} from "element-plus";
import {ManagementTable,ManagedDialog,FloatingError,setErrorFeedback} from "@appnexus/ui";
import ProductAttributes from "./ProductAttributes.vue";
import type {ProductApi,ProductField,ProductRow} from "./product";
/** 规格与SKU显式维护，组合明细独立；复用统一表格和弹窗，不制造自动SKU。 */
const props=defineProps<{id:string;version:number;readonly:boolean;readonlyView?:boolean;api:ProductApi;fields:ProductField[];errorText:(e:unknown)=>string}>();const emit=defineEmits<{changed:[]}>();const {t}=useI18n();
const data=ref<Awaited<ReturnType<ProductApi['structure']>>>(),busy=ref(false),error=ref(""),open=ref(false),kind=ref("specification"),attributesValid=ref(true),detail=ref<Record<string,any>>(),detailOpen=ref(false),form=ref<FormInstance>(),candidates=ref<ProductRow[]>([]),candidatePage=ref(1),candidateTotal=ref(0),candidateKeyword=ref("");
const draft=reactive({name:"",description:"",specificationId:"",code:"",componentId:"",quantity:"1"}),values=reactive<Record<string,string|string[]>>({});
const specificationFields=computed(()=>data.value?.specificationFields??props.fields);
async function load(){try{data.value=await props.api.structure(props.id);}catch(e){await setErrorFeedback(error,props.errorText(e));}}
/** 候选只按授权分页读取，不将前100条当作完整商品目录。 */
async function findComponents(keyword:string,page=1){candidateKeyword.value=keyword;candidatePage.value=page;try{const result=await props.api.list({name:keyword,code:"",status:"ENABLED",archived:false,page,size:20});candidates.value=result.rows.filter(r=>r.id!==props.id);candidateTotal.value=result.total;}catch(e){await setErrorFeedback(error,props.errorText(e));}}
async function edit(type:string){kind.value=type;Object.assign(draft,{name:"",description:"",specificationId:"",code:"",componentId:"",quantity:"1"});for(const key of Object.keys(values))delete values[key];if(type==='component'){try{await findComponents('');}catch(e){await setErrorFeedback(error,props.errorText(e));return;}}open.value=true;}
/** 保存是一个父CAS命令，成功后重新读取整个聚合，不复用陈旧版本。 */
async function save(){if(busy.value||!await form.value?.validate().catch(()=>false))return;if(kind.value==='specification'&&data.value?.mode==='STANDARD'&&!specificationFields.value.length){await setErrorFeedback(error,t('productV1.specificationTemplateRequired'));return;}if(kind.value==='specification'&&data.value?.mode==='CUSTOM'){if(!attributesValid.value)return;const missing=specificationFields.value.find(f=>f.requiredFlag&&(values[f.templateItemId]===undefined||values[f.templateItemId]===''||Array.isArray(values[f.templateItemId])&&!(values[f.templateItemId] as string[]).length));if(missing){await setErrorFeedback(error,t('masterData.required')+' · '+missing.name);return;}}
 busy.value=true;try{if(kind.value==='specification')await props.api.createSpecification(props.id,{name:draft.name,description:draft.description,values:data.value?.mode==='STANDARD'?specificationFields.value.map(f=>({templateItemId:f.templateItemId,value:values[f.templateItemId]})):specificationFields.value.flatMap(f=>{const v=values[f.templateItemId];if(v===undefined||v===''||Array.isArray(v)&&!v.length)return [];return [Array.isArray(v)?{templateItemId:f.templateItemId,value:null,optionIds:v.filter(x=>!x.startsWith('custom:')),customValues:v.filter(x=>x.startsWith('custom:')).map(x=>x.slice(7))}:{templateItemId:f.templateItemId,value:v}];}),version:props.version});else if(kind.value==='sku')await props.api.createSku(props.id,{specificationId:draft.specificationId,code:draft.code,version:props.version});else {const child=candidates.value.find(r=>r.id===draft.componentId);await props.api.addComponent(props.id,{componentId:draft.componentId,quantity:draft.quantity,componentVersion:child?.version,version:props.version});}open.value=false;emit('changed');}catch(e){await setErrorFeedback(error,props.errorText(e));}finally{busy.value=false;}}
async function toggle(type:string,row:Record<string,any>){try{await ElMessageBox.confirm(t('productStructure.stateHint'),t('productStructure.title'),{confirmButtonText:t(row.enabled?'masterData.disable':'masterData.enable'),cancelButtonText:t('masterData.cancel')});}catch{return;}busy.value=true;try{await props.api.structureState(props.id,type,String(row.id),{enabled:!row.enabled,rowVersion:row.version,version:props.version});emit('changed');}catch(e){await setErrorFeedback(error,props.errorText(e));}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section><h3>{{t('productStructure.title')}}</h3><FloatingError :title="error"/><p>{{t('productStructure.'+(data?.mode||'NONE'))}}</p>
<ManagementTable :readonly-view="readonlyView" v-for="type in [...(data?.mode&&data.mode!=='NONE'?['specification','sku']:[]),...(data?.form==='COMPOSITE'?['component']:[])]" :key="type" :title="t('productStructure.'+type)" :rows="type==='specification'?data?.specifications??[]:type==='sku'?data?.skus??[]:data?.components??[]" :loading="busy" :columns="[{key:'status',label:t('masterData.status'),width:100},{key:'identity',label:t('masterData.name'),minWidth:180},...(type==='component'?[{key:'quantity',label:t('productStructure.componentQuantity'),width:160}]:[]),{key:'effective',label:t('productStructure.effective'),width:100},{key:'operations',label:t('masterData.actions'),width:180}]" @refresh="load"><template #actions><el-button v-if="!readonly&&(type==='component'||data?.mode!=='NONE')" v-operation="type==='specification'?'Product.createSpecification':type==='sku'?'Product.createSku':'Product.addComponent'" :disabled="busy" @click="edit(type)">{{t('masterData.create')}}</el-button></template><template #identity="{row}">{{row.name||row.code}}</template><template #quantity="{row}">{{row.quantity?String(row.quantity).replace(/(\.[0-9]*?)0+$/,'$1').replace(/\.$/,''):'—'}}</template><template #status="{row}"><el-tag class="app-status-tag" :type="!row.retiredAt&&row.enabled?'success':'info'">{{row.retiredAt?t('productStructure.retired'):t(row.enabled?'masterData.enabled':'masterData.disabled')}}</el-tag></template><template #effective="{row}">{{t(row.effective?'productV1.yes':'productV1.no')}}</template><template #operations="{row}"><ProductHistoryButton :id="id" :api="api" :error-text="errorText" link :subject="{collection:type==='specification'?'specifications':type==='sku'?'skus':'components',id:String(type==='component'?row.componentId:row.id)}" /><el-button v-if="!readonlyView&&type==='specification'" v-operation="'Product.readStructure'" link type="primary" @click="detail=row;detailOpen=true">{{t('partner.view')}}</el-button><el-link v-else-if="type==='specification'" href="#specification-detail" v-operation="'Product.readStructure'" @click.prevent="detail=row;detailOpen=true">{{t('partner.view')}}</el-link><el-button v-if="!readonly&&!row.retiredAt&&(type!=='component'||row.enabled)" v-operation="'Product.setStructureState'" link :disabled="busy" @click="toggle(type,row)">{{t(row.enabled?'masterData.disable':'masterData.enable')}}</el-button></template></ManagementTable>
<ManagedDialog v-model="open" :title="t('productStructure.'+kind)" :busy="busy"><el-form ref="form" :model="draft" label-position="top" class="business-border-label-form" @submit.prevent="save"><template v-if="kind==='specification'"><el-form-item :label="t('masterData.name')" prop="name" :rules="[{required:true,message:t('masterData.required')}]"><el-input v-model="draft.name" maxlength="200"/></el-form-item><el-form-item :label="t('productV1.description')"><el-input v-model="draft.description" type="textarea" maxlength="2000"/></el-form-item><template v-if="data?.mode==='STANDARD'"><el-form-item v-for="field in specificationFields" :key="field.templateItemId" :label="field.name" :required="true"><el-select v-if="field.dataType==='SINGLE_SELECT'" v-model="values[field.templateItemId]"><el-option v-for="o in field.options.filter(o=>o.enabled)" :key="o.id" :value="o.id" :label="o.label"/></el-select><el-select v-else-if="field.dataType==='BOOLEAN'" v-model="values[field.templateItemId]"><el-option value="true" :label="t('productV1.yes')"/><el-option value="false" :label="t('productV1.no')"/></el-select><el-input v-else :model-value="values[field.templateItemId] as string" maxlength="32" @update:model-value="value=>values[field.templateItemId]=value"/></el-form-item></template><ProductAttributes v-else :fields="specificationFields" :values="values" :disabled="busy" @change="(id,value)=>values[id]=value" @valid="v=>attributesValid=v"/></template><template v-else-if="kind==='sku'"><el-form-item :label="t('masterData.code')" prop="code" :rules="[{required:true,message:t('masterData.required')}]"><el-input v-model="draft.code" maxlength="64"/></el-form-item><el-form-item :label="t('productStructure.specification')" prop="specificationId" :rules="[{required:true,message:t('masterData.required')}]"><el-select v-model="draft.specificationId"><el-option v-for="s in data?.specifications.filter(s=>s.enabled&&!s.retiredAt)??[]" :key="s.id" :value="s.id" :label="s.name"/></el-select></el-form-item></template><template v-else><el-form-item :label="t('productStructure.component')" prop="componentId" :rules="[{required:true,message:t('masterData.required')}]"><el-select v-model="draft.componentId" filterable remote :remote-method="q=>findComponents(q)"><el-option v-for="p in candidates" :key="p.id" :value="p.id" :label="p.code+' / '+p.name"/><template #footer><el-pagination :current-page="candidatePage" :page-size="20" :total="candidateTotal" layout="prev,next" @current-change="p=>findComponents(candidateKeyword,p)"/></template></el-select></el-form-item><el-form-item :label="t('productStructure.componentQuantity')" prop="quantity" :rules="[{required:true,message:t('masterData.required')},{pattern:/^(0|[1-9][0-9]{0,17})([.][0-9]{1,12})?$/,message:t('productConversion.invalid')},{validator:(_rule:any,value:string,callback:(error?:Error)=>void)=>callback(/^0([.]0+)?$/.test(value)?new Error(t('productConversion.invalid')):undefined)}]"><el-input v-model="draft.quantity" maxlength="32"/></el-form-item></template></el-form><template #footer><el-button v-operation="kind==='specification'?'Product.createSpecification':kind==='sku'?'Product.createSku':'Product.addComponent'" type="primary" :loading="busy" @click="save">{{t('masterData.save')}}</el-button></template></ManagedDialog><ManagedDialog v-model="detailOpen" :title="t('productStructure.specification')"><section class="readonly-detail-section"><dl class="detail-field-grid"><div class="detail-readonly-field"><dt>{{ t('masterData.name') }}</dt><dd>{{detail?.name}}</dd></div><div class="detail-readonly-field"><dt>{{ t('productV1.description') }}</dt><dd>{{detail?.description||'—'}}</dd></div><div class="detail-readonly-field" v-for="field in detail?.values??[]" :key="field.templateItemId"><dt>{{ field.name+(field.unitCode?' ('+field.unitCode+')':'') }}</dt><dd>{{field.dataType==='BOOLEAN'?t(field.booleanValue?'productV1.yes':'productV1.no'):field.textValue??field.dateValue??field.integerValue??field.decimalValue??(field.choices.map((o:any)=>o.label).join(' / ')||'—')}}</dd></div></dl></section></ManagedDialog></section></template>
